def check_m2(x1):
    # Condition 3: 1/x1 + x1/x2 = 15/16
    # x2 = (16 * x1^2) / (15 * x1 - 16)
    denominator = 15 * x1 - 16
    if denominator <= 0:
        return None
    numerator = 16 * x1**2

    # Check if x2 is an integer
    if numerator % denominator != 0:
        return None

    x2 = numerator // denominator

    # Condition 2: x2 >= 1 + x1^3 - x1^2
    required_x2 = 1 + x1**3 - x1**2

    if x2 >= required_x2:
        return (x1, x2)
    else:
        return None

print("M=2 solutions for x1=2 to 10:")
solutions_m2 = []
for x1 in range(2, 11):
    sol = check_m2(x1)
    if sol:
        solutions_m2.append(sol)
        print(f"Found solution for x1={x1}: {sol}")

print(f"Total solutions found for M=2: {len(solutions_m2)}")

